cat > /workspace/dev/gen.py <<'PYEOF'
"""Random request generator for differential testing."""
import json, random

TOPOS = [
    lambda r: ["leaf-spine", r.randint(2, 5), r.randint(1, 3)],
    lambda r: ["clos", 4, r.choice(["tor", "pod"]), r.randint(0, 1)],
    lambda r: ["clos", 6, r.choice(["tor", "pod"]), r.randint(0, 1)],
    lambda r: ["torus2d", r.randint(3, 5), r.choice(["host", "row"])],
    lambda r: ["torus3d", 3, r.choice(["host", "line"])],
    lambda r: ["dragonfly", 2, 1, 1, r.choice(["router", "group", "target"])],
    lambda r: ["dragonfly", 4, 1, 3, r.choice(["router", "group", "target"])],
    lambda r: ["dragonfly", 3, 2, 1, r.choice(["router", "group", "target"])],
    lambda r: ["dragonfly-plus", r.randint(2, 3), r.randint(1, 2), r.randint(1, 2), 1,
               r.randint(0, 1), r.choice(["group", "tor"])],
    lambda r: ["dragonfly-plus", 2, 2, 1, 1, 0, r.choice(["group", "tor"])],
]


def gen_session(rng):
    topo = rng.choice(TOPOS)(rng)
    if topo[0] == 'clos':
        k = topo[1]
        T = k * k // 2
        ntpl = T * (T - 1 if topo[3] else T - k // 2)
    elif topo[0] == 'leaf-spine':
        ntpl = topo[1] * (topo[1] - 1)
    elif topo[0] == 'torus2d':
        ntpl = (topo[1] ** 2) * (topo[1] ** 2 - 1)
    elif topo[0] == 'torus3d':
        m = topo[1] ** 3
        ntpl = m * (m - 1)
    elif topo[0] == 'dragonfly':
        m = topo[1] * topo[2]
        ntpl = m * (m - 1)
    else:
        m = topo[1] * topo[2]
        ntpl = m * (m - 1)
    if topo[0] == 'leaf-spine':
        n = topo[1] + topo[2]
    elif topo[0] == 'clos':
        n = topo[1] * topo[1]
    elif topo[0] == 'torus2d':
        n = topo[1] ** 2
    elif topo[0] == 'torus3d':
        n = topo[1] ** 3
    elif topo[0] == 'dragonfly':
        n = topo[1] * topo[2]
    else:
        n = topo[1] * (topo[2] + topo[3])
    G = rng.randint(1, 6)
    D = rng.randint(0, 12)
    groups = [[rng.randint(0, 64), rng.randint(1, 10 ** 12)] for _ in range(G)]
    tasks = []
    for _ in range(D):
        tasks.append([rng.randrange(ntpl), rng.randrange(G), rng.randint(1, 30),
                      rng.randint(0, 4), rng.randint(0, 1)])
    caps = [rng.randint(0, 40) for _ in range(n)]
    def q():
        return {"groups": [rng.randrange(G) for _ in range(rng.randint(0, 4))],
                "nodes": [rng.randrange(n) for _ in range(rng.randint(0, 4))],
                "tasks": [rng.randrange(D) for _ in range(rng.randint(0, 4))] if D else []}
    txs = []
    for _ in range(rng.randint(0, 12)):
        edits = []
        for _ in range(rng.randint(0, 8)):
            op = rng.choice(['move', 'weight', 'class', 'bind', 'pin', 'quota', 'budget', 'cap'])
            if op in ('move', 'weight', 'class', 'bind', 'pin'):
                idx = rng.randrange(D) if D else 0
                if op == 'move':
                    val = rng.randrange(G)
                elif op == 'weight':
                    val = rng.randint(1, 30)
                elif op == 'class':
                    val = rng.randint(0, 4)
                elif op == 'bind':
                    val = rng.randrange(ntpl)
                else:
                    val = rng.randint(0, 1)
            elif op in ('quota', 'budget'):
                idx = rng.randrange(G)
                val = rng.randint(0, 64) if op == 'quota' else rng.randint(1, 10 ** 12)
            else:
                idx = rng.randrange(n)
                val = rng.randint(0, 40)
            if D == 0 and op in ('move', 'weight', 'class', 'bind', 'pin'):
                continue
            edits.append([op, idx, val])
        txs.append({"revision": rng.randint(0, 5), "edits": edits, "query": q()})
    return {"topology": topo, "caps": caps, "groups": groups, "tasks": tasks,
            "query": q(), "transactions": txs}


def gen_request(seed):
    rng = random.Random(seed)
    return {"version": 2, "sessions": [gen_session(rng) for _ in range(rng.randint(0, 3))]}
PYEOF
